/* ============================================================
   DESIGN TOKENS
   ============================================================ */
:root {
  --cream: #EDE8D8;
  --dark: #1A1710;
  --brown: #2A2318;
  --taupe: #8A7D68;
  --sage: #6B7A54;
  --gold: #C8B88A;
  --en: "TTNorthem", Georgia, serif;
  --ar: "Amiri", serif;
  --px: 60px;
}

/* ============================================================
   RESET
   ============================================================ */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  background: var(--dark);
  color: var(--cream);
  font-family: var(--en);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

/* ============================================================
   FONTS (Embedded)
   ============================================================ */
@font-face{font-family:"TTNorthem";font-weight:300;src:url("data:font/ttf;base64," type="font/ttf")}

@font-face{font-family:"TTNorthem";font-weight:400;src:url("data:font/ttf;base64," type="font/ttf")}

/* ============================================================
   NAVIGATION
   ============================================================ */
nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px var(--px);
  background: linear-gradient(to bottom, rgba(26, 23, 16, 0.95) 0%, transparent 100%);
}

.nav-logo svg {
  width: 46px;
  height: 42px;
}

.nav-links {
  display: flex;
  gap: 34px;
}

.nav-links a {
  font-family: var(--en);
  font-weight: 300;
  font-size: 10px;
  letter-spacing: 0.22em;
  color: rgba(237, 232, 216, 0.52);
  text-transform: uppercase;
  transition: color 0.3s;
}

.nav-links a:hover {
  color: var(--gold);
}

.nav-book {
  font-family: var(--en);
  font-weight: 400;
  font-size: 10px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--dark);
  background: var(--gold);
  padding: 12px 30px;
  transition: background 0.3s;
}

.nav-book:hover {
  background: var(--cream);
}

/* Hamburger */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 8px;
  z-index: 110;
  background: none;
  border: none;
}

.nav-toggle span {
  display: block;
  width: 22px;
  height: 1px;
  background: var(--cream);
  transition: all 0.35s ease;
  transform-origin: center;
}

.nav-toggle.active span:nth-child(1) {
  transform: translateY(6px) rotate(45deg);
}

.nav-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
  transform: translateY(-6px) rotate(-45deg);
}

/* Mobile Overlay */
.nav-mobile {
  display: flex;
  position: fixed;
  inset: 0;
  z-index: 99;
  background: rgba(26, 23, 16, 0.97);
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 40px;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.4s ease, visibility 0.4s ease;
}

.nav-mobile.active {
  opacity: 1;
  visibility: visible;
}

.nav-mobile-links {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 32px;
}

.nav-mobile-links a {
  font-family: var(--en);
  font-weight: 300;
  font-size: 12px;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  color: rgba(237, 232, 216, 0.52);
  transition: color 0.3s;
}

.nav-mobile-links a:hover {
  color: var(--gold);
}

.nav-mobile-book {
  font-family: var(--en);
  font-weight: 400;
  font-size: 10px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--dark);
  background: var(--gold);
  padding: 16px 40px;
  transition: background 0.3s;
}

.nav-mobile-book:hover {
  background: var(--cream);
}

/* ============================================================
   HERO
   ============================================================ */
.hero {
  position: relative;
  height: 100vh;
  min-height: 700px;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
  background: linear-gradient(135deg, #2A2318 0%, #1A1710 40%, #0f0d09 100%);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-image: url("data:image/jpeg;base64,");
  background-size: auto;
  background-position: center;
  background-attachment: fixed;
  animation: hz 18s ease-in-out infinite alternate;
}

@keyframes hz {
  from { transform: scale(1.06); }
  to { transform: scale(1.0); }
}

.hero-ov {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to top,
    rgba(26, 23, 16, 0.97) 0%,
    rgba(26, 23, 16, 0.62) 28%,
    rgba(26, 23, 16, 0.1) 65%,
    transparent 100%
  );
}

.hero-c {
  position: relative;
  z-index: 2;
  width: 100%;
  padding: 0 var(--px) 80px;
  display: flex;
  flex-direction: row;
  gap: 60px;
  align-items: flex-end;
}

.hero-ar-wrap {
  direction: rtl;
  flex: 1;
}

.hero-ar {
  font-family: var(--ar);
  font-style: italic;
  font-size: clamp(38px, 4.8vw, 64px);
  line-height: 1.04;
  letter-spacing: -0.01em;
  color: var(--cream);
  display: block;
}

.hero-ar .gold {
  color: var(--gold);
}

.hero-ar-en {
  font-family: var(--en);
  font-weight: 300;
  font-size: 13px;
  color: rgba(237, 232, 216, 0.28);
  direction: ltr;
  margin-top: 14px;
  letter-spacing: 0.09em;
  display: block;
}

.hero-right {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 18px;
  min-width: 280px;
  flex-shrink: 0;
}

.hero-lbl {
  font-family: var(--en);
  font-weight: 300;
  font-size: 9px;
  letter-spacing: 0.32em;
  color: rgba(237, 232, 216, 0.3);
  text-transform: uppercase;
}

.hero-divider {
  width: 36px;
  height: 0.5px;
  background: var(--gold);
  opacity: 0.45;
}

.hero-desc {
  font-family: var(--ar);
  font-size: 14px;
  line-height: 1.88;
  color: rgba(237, 232, 216, 0.52);
  max-width: 300px;
  direction: rtl;
}

.hero-btn {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-family: var(--en);
  font-weight: 400;
  font-size: 10px;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--dark);
  background: var(--gold);
  padding: 16px 36px;
  transition: all 0.35s;
}

.hero-btn:hover {
  background: var(--cream);
  gap: 18px;
}

.hero-btn::after {
  content: "\2192";
  font-size: 13px;
}

.scroll-hint {
  position: absolute;
  bottom: 26px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
}

.scroll-hint span {
  font-family: var(--en);
  font-weight: 300;
  font-size: 8px;
  letter-spacing: 0.26em;
  color: rgba(237, 232, 216, 0.18);
  text-transform: uppercase;
}

.scroll-line {
  width: 0.5px;
  height: 40px;
  background: linear-gradient(to bottom, var(--gold), transparent);
  opacity: 0.3;
  animation: sp 2.2s ease-in-out infinite;
}

@keyframes sp {
  0%, 100% { opacity: 0.1; }
  50% { opacity: 0.45; }
}

/* ============================================================
   PHILOSOPHY
   ============================================================ */
.philosophy {
  position: relative;
  background: #EDE8D8 !important;
  background-image: url("data:image/png;base64,");
  background-size: auto;
  background-position: center;
  background-attachment: fixed;
  color: var(--brown);
  padding: 110px var(--px);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 72px;
  align-items: center;
  min-height: 620px;
  overflow: hidden;
}

.philosophy::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background-image:
    radial-gradient(circle at 20% 50%, rgba(107, 122, 84, 0.08) 0%, transparent 50%),
    radial-gradient(circle at 80% 30%, rgba(200, 184, 138, 0.06) 0%, transparent 40%),
    radial-gradient(circle at 50% 80%, rgba(138, 125, 104, 0.05) 0%, transparent 45%);
  background-size: 100% 100%;
}

.ph-content {
  position: relative;
  z-index: 2;
}

.ph-label {
  font-family: var(--en);
  font-weight: 300;
  font-size: 9px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--taupe);
  margin-bottom: 28px;
}

.ph-heading {
  font-family: var(--ar);
  font-style: italic;
  font-size: clamp(32px, 3.8vw, 52px);
  line-height: 1.32;
  color: var(--brown);
  direction: rtl;
}

.ph-heading em {
  color: var(--sage);
  font-style: italic;
}

.ph-en {
  font-family: var(--en);
  font-weight: 300;
  font-size: clamp(12px, 1.3vw, 17px);
  color: rgba(42, 35, 24, 0.3);
  margin-top: 12px;
  direction: ltr;
  letter-spacing: 0.07em;
}

.ph-right {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.ph-line {
  width: 40px;
  height: 0.5px;
  background: var(--gold);
  opacity: 0.5;
  align-self: flex-end;
}

.ph-body {
  font-family: var(--ar);
  font-size: 14px;
  line-height: 1.92;
  color: rgba(42, 35, 24, 0.62);
  direction: rtl;
  text-align: right;
}

/* ============================================================
   STAFF
   ============================================================ */
.staff-section {
  position: relative;
  height: 92vh;
  min-height: 580px;
  overflow: hidden;
  background: linear-gradient(135deg, #2A2318 0%, #1A1710 100%);
}

.staff-section img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 20%;
}

.staff-ov {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(26, 23, 16, 0.88) 0%, rgba(26, 23, 16, 0.28) 55%, transparent 100%);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 0 var(--px) 80px;
}

.staff-lbl {
  font-family: var(--en);
  font-weight: 300;
  font-size: 9px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: rgba(237, 232, 216, 0.38);
  margin-bottom: 18px;
}

.staff-h {
  font-family: var(--ar);
  font-style: italic;
  font-size: clamp(40px, 5.5vw, 72px);
  color: var(--cream);
  direction: rtl;
  line-height: 1.18;
}

.staff-en {
  font-family: var(--en);
  font-weight: 300;
  font-size: clamp(13px, 1.6vw, 22px);
  color: rgba(237, 232, 216, 0.27);
  direction: ltr;
  margin-top: 10px;
  letter-spacing: 0.08em;
}

/* ============================================================
   COUNTER / RECEPTION SPLIT
   ============================================================ */
.counter-split {
  display: grid;
  grid-template-columns: 55% 45%;
  min-height: 580px;
}

.cs-img {
  position: relative;
  overflow: hidden;
}

.cs-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.9s;
}

.cs-img:hover img {
  transform: scale(1.03);
}

.cs-text {
  background: var(--dark);
  padding: 72px 56px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 24px;
  border-left: 0.5px solid rgba(237, 232, 216, 0.06);
}

.cs-lbl {
  font-family: var(--en);
  font-weight: 300;
  font-size: 9px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--taupe);
}

.cs-h {
  font-family: var(--ar);
  font-style: italic;
  font-size: clamp(28px, 3vw, 46px);
  color: var(--cream);
  direction: rtl;
  line-height: 1.28;
}

.cs-en {
  font-family: var(--en);
  font-weight: 300;
  font-size: clamp(11px, 1.2vw, 17px);
  color: rgba(237, 232, 216, 0.24);
  direction: ltr;
  letter-spacing: 0.07em;
}

.cs-body {
  font-family: var(--ar);
  font-size: 13px;
  line-height: 1.88;
  color: rgba(237, 232, 216, 0.48);
  direction: rtl;
}

.cs-cta {
  font-family: var(--en);
  font-weight: 400;
  font-size: 10px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold);
  border-bottom: 0.5px solid rgba(200, 184, 138, 0.4);
  padding-bottom: 3px;
  transition: all 0.3s;
  width: fit-content;
}

.cs-cta:hover {
  color: var(--cream);
  border-color: var(--cream);
}

/* ============================================================
   EXPERIENCE STRIP
   ============================================================ */
.exp-strip {
  background: var(--sage);
  padding: 80px var(--px);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

.exp-item {
  padding: 0 48px;
  border-right: 0.5px solid rgba(237, 232, 216, 0.14);
  direction: rtl;
  text-align: right;
}

.exp-item:first-child {
  padding-right: 0;
  padding-left: 48px;
}

.exp-item:last-child {
  border-right: none;
}

.exp-n {
  font-family: var(--en);
  font-weight: 300;
  font-size: 54px;
  color: rgba(237, 232, 216, 0.1);
  line-height: 1;
  margin-bottom: 18px;
}

.exp-title {
  font-family: var(--ar);
  font-style: italic;
  font-size: 22px;
  color: var(--cream);
  margin-bottom: 4px;
}

.exp-en-sub {
  font-family: var(--en);
  font-weight: 300;
  font-size: 12px;
  color: rgba(237, 232, 216, 0.25);
  direction: ltr;
  text-align: left;
  margin-bottom: 12px;
  letter-spacing: 0.06em;
}

.exp-desc {
  font-family: var(--ar);
  font-size: 12px;
  line-height: 1.8;
  color: rgba(237, 232, 216, 0.52);
}

/* ============================================================
   SERVICES
   ============================================================ */
.services {
  background: var(--dark);
  padding: 100px var(--px);
}

.svc-hdr {
  display: flex;
  flex-direction: row-reverse;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 52px;
  padding-bottom: 28px;
  border-bottom: 0.5px solid rgba(237, 232, 216, 0.07);
}

.svc-lbl {
  font-family: var(--en);
  font-weight: 300;
  font-size: 9px;
  letter-spacing: 0.28em;
  color: rgba(237, 232, 216, 0.26);
  text-transform: uppercase;
}

.svc-h2 {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
}

.svc-h2 .ar {
  font-family: var(--ar);
  font-style: italic;
  font-size: clamp(28px, 3vw, 42px);
  color: var(--cream);
  direction: rtl;
}

.svc-h2 .en {
  font-family: var(--en);
  font-weight: 300;
  font-size: clamp(11px, 1.1vw, 16px);
  color: rgba(237, 232, 216, 0.24);
  direction: ltr;
  letter-spacing: 0.09em;
}

.svc-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 2px;
}

.svc-card {
  padding: 48px 42px;
  background: rgba(237, 232, 216, 0.03);
  border: 0.5px solid rgba(237, 232, 216, 0.06);
  position: relative;
  overflow: hidden;
  transition: background 0.35s;
  direction: rtl;
}

.svc-card::after {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 2px;
  height: 0;
  background: var(--gold);
  transition: height 0.55s ease;
}

.svc-card:hover::after {
  height: 100%;
}

.svc-card:hover {
  background: rgba(237, 232, 216, 0.055);
}

.svc-ar {
  font-family: var(--ar);
  font-style: italic;
  font-size: 27px;
  color: var(--cream);
  margin-bottom: 4px;
}

.svc-en {
  font-family: var(--en);
  font-weight: 300;
  font-size: 12px;
  color: rgba(237, 232, 216, 0.24);
  direction: ltr;
  letter-spacing: 0.09em;
  margin-bottom: 20px;
}

.svc-items {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.svc-items span {
  font-family: var(--ar);
  font-size: 12px;
  color: rgba(237, 232, 216, 0.36);
  padding-right: 14px;
  border-right: 0.5px solid rgba(237, 232, 216, 0.12);
}

/* ============================================================
   BOOKING / CTA
   ============================================================ */
.booking {
  position: relative;
  overflow: hidden;
  background: var(--brown);
  padding: 110px var(--px);
  text-align: center;
}

.booking::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at 30% 20%, rgba(200, 184, 138, 0.06) 0%, transparent 50%),
    radial-gradient(ellipse at 70% 70%, rgba(138, 125, 104, 0.08) 0%, transparent 40%),
    radial-gradient(circle at 50% 50%, rgba(237, 232, 216, 0.03) 0%, transparent 60%);
}

.booking-flower {
  position: absolute;
  inset: 0;
  background-image: url("data:image/jpeg;base64,");
  background-size: cover;
  background-position: center;
}

.booking-ov {
  position: absolute;
  inset: 0;
  background: rgba(42, 35, 24, 0.55);
  z-index: 1;
}

.bk-inner {
  position: relative;
  z-index: 2;
}

.bk-lbl {
  font-family: var(--en);
  font-weight: 300;
  font-size: 9px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: rgba(237, 232, 216, 0.22);
  margin-bottom: 22px;
}

.bk-h2 {
  font-family: var(--ar);
  font-style: italic;
  font-size: clamp(50px, 7vw, 88px);
  color: var(--cream);
  direction: rtl;
  line-height: 1.15;
  margin-bottom: 8px;
}

.bk-en {
  font-family: var(--en);
  font-weight: 300;
  font-size: clamp(15px, 1.8vw, 26px);
  color: rgba(237, 232, 216, 0.22);
  direction: ltr;
  letter-spacing: 0.09em;
  margin-bottom: 44px;
}

.bk-btn {
  display: inline-block;
  font-family: var(--en);
  font-weight: 400;
  font-size: 11px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--dark);
  background: var(--gold);
  padding: 20px 62px;
  transition: background 0.3s;
}

.bk-btn:hover {
  background: var(--cream);
}

.bk-contact {
  margin-top: 36px;
  font-family: var(--en);
  font-weight: 300;
  font-size: 11px;
  letter-spacing: 0.1em;
  color: rgba(237, 232, 216, 0.2);
}

/* ============================================================
   FOOTER
   ============================================================ */
footer {
  background: var(--dark);
  border-top: 0.5px solid rgba(237, 232, 216, 0.05);
  padding: 56px var(--px) 32px;
  display: grid;
  grid-template-columns: 1.2fr 1fr 1fr;
  gap: 40px;
  direction: rtl;
}

.ft-brand {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.ft-brand svg {
  width: 36px;
  height: 33px;
}

.ft-tag-ar {
  font-family: var(--ar);
  font-style: italic;
  font-size: 14px;
  color: rgba(237, 232, 216, 0.22);
  direction: rtl;
}

.ft-tag-en {
  font-family: var(--en);
  font-weight: 300;
  font-size: 11px;
  color: rgba(237, 232, 216, 0.12);
  direction: ltr;
  letter-spacing: 0.06em;
}

.ft-col-h {
  font-family: var(--en);
  font-weight: 300;
  font-size: 9px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(237, 232, 216, 0.32);
  margin-bottom: 8px;
}

.ft-links {
  display: flex;
  flex-direction: column;
  gap: 10px;
  direction: rtl;
}

.ft-links li {
  font-family: var(--en);
  font-weight: 300;
  font-size: 11px;
  color: rgba(237, 232, 216, 0.32);
  direction: rtl;
  letter-spacing: 0.04em;
}

.ft-links a {
  font-family: var(--ar);
  font-size: 12px;
  color: rgba(237, 232, 216, 0.36);
  direction: rtl;
  transition: color 0.3s;
}

.ft-links a:hover {
  color: var(--gold);
}

.ft-bottom {
  grid-column: 1 / -1;
  border-top: 0.5px solid rgba(237, 232, 216, 0.05);
  padding-top: 22px;
  margin-top: 10px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.ft-copy {
  font-family: var(--en);
  font-weight: 300;
  font-size: 10px;
  color: rgba(237, 232, 216, 0.14);
  letter-spacing: 0.08em;
}

.ft-social {
  display: flex;
  gap: 20px;
}

.ft-social a {
  font-family: var(--en);
  font-weight: 300;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(237, 232, 216, 0.18);
  transition: color 0.3s;
}

.ft-social a:hover {
  color: var(--gold);
}

/* ============================================================
   CONTACT PAGE
   ============================================================ */
.nav-back {
  font-family: var(--en);
  font-weight: 300;
  font-size: 10px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(237, 232, 216, 0.52);
  text-decoration: none;
  transition: color 0.3s;
}

.nav-back:hover {
  color: var(--gold);
}

.contact-page {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 120px var(--px) 60px;
}

.contact-inner {
  text-align: center;
  max-width: 520px;
  width: 100%;
}

.contact-label {
  font-family: var(--en);
  font-weight: 300;
  font-size: 9px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--taupe);
  margin-bottom: 28px;
}

.contact-heading {
  font-family: var(--ar);
  font-style: italic;
  font-size: clamp(36px, 5vw, 56px);
  color: var(--cream);
  line-height: 1.2;
  direction: rtl;
  margin-bottom: 8px;
}

.contact-sub {
  font-family: var(--en);
  font-weight: 300;
  font-size: clamp(12px, 1.3vw, 17px);
  color: rgba(237, 232, 216, 0.24);
  direction: ltr;
  letter-spacing: 0.07em;
  margin-bottom: 56px;
}

.contact-links {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.contact-card {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 24px 32px;
  background: rgba(237, 232, 216, 0.03);
  border: 0.5px solid rgba(237, 232, 216, 0.08);
  text-decoration: none;
  transition: background 0.35s, border-color 0.35s;
}

.contact-card:hover {
  background: rgba(237, 232, 216, 0.06);
  border-color: rgba(200, 184, 138, 0.3);
}

.contact-card.whatsapp:hover {
  border-color: rgba(37, 211, 102, 0.5);
}

.contact-card.instagram:hover {
  border-color: rgba(225, 48, 108, 0.5);
}

.contact-card.phone:hover {
  border-color: rgba(200, 184, 138, 0.5);
}

.contact-icon {
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  color: var(--cream);
}

.contact-card.whatsapp .contact-icon {
  color: #25D366;
}

.contact-card.instagram .contact-icon {
  color: #E1306C;
}

.contact-card-text {
  display: flex;
  flex-direction: column;
  gap: 4px;
  direction: rtl;
}

.contact-card-title {
  font-family: var(--en);
  font-weight: 400;
  font-size: 14px;
  letter-spacing: 0.06em;
  color: var(--cream);
  direction: ltr;
  text-align: left;
}

.contact-card-sub {
  font-family: var(--ar);
  font-size: 13px;
  color: rgba(237, 232, 216, 0.36);
  direction: rtl;
  text-align: right;
}

/* ============================================================
   SEPARATOR
   ============================================================ */
.sep {
  width: 100%;
  height: 0.5px;
  background: linear-gradient(to right, transparent, var(--gold), transparent);
  opacity: 0.16;
}

/* ============================================================
   FOCUS & ACCESSIBILITY
   ============================================================ */
:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

/* ============================================================
   RESPONSIVE — TABLET LANDSCAPE (<=1200px)
   ============================================================ */
@media (max-width: 1200px) {
  :root { --px: 40px; }
  .hero-c { gap: 40px; }
  .hero-right { min-width: 240px; }
  .exp-item { padding: 0 32px; }
  .exp-item:first-child { padding-left: 32px; }
}

/* ============================================================
   RESPONSIVE — TABLET PORTRAIT (<=1024px)
   ============================================================ */
@media (max-width: 1024px) {
  :root { --px: 32px; }

  .nav-links,
  .nav-book { display: none; }
  .nav-toggle { display: flex; }

  .hero-c {
    flex-direction: column;
    align-items: flex-start;
    gap: 32px;
    padding-bottom: 60px;
  }
  .hero-right { min-width: unset; width: 100%; }
  .hero-desc { max-width: 100%; }

  .philosophy {
    grid-template-columns: 1fr;
    gap: 48px;
    padding-top: 80px;
    padding-bottom: 80px;
    min-height: auto;
  }

  .counter-split { grid-template-columns: 1fr; min-height: auto; }
  .cs-img { height: 50vh; min-height: 320px; }
  .cs-text { padding: 56px 40px; }

  .exp-strip {
    grid-template-columns: 1fr;
    gap: 0;
    padding: 60px var(--px);
  }
  .exp-item {
    padding: 36px 0;
    border-right: none;
    border-bottom: 0.5px solid rgba(237, 232, 216, 0.14);
    text-align: center;
  }
  .exp-item:first-child { padding-left: 0; }
  .exp-item:last-child { border-bottom: none; padding-bottom: 0; }
  .exp-en-sub { text-align: center; direction: ltr; }

  .services { padding: 80px var(--px); }
  .svc-hdr { flex-direction: column; align-items: flex-end; gap: 12px; }
  .svc-grid { grid-template-columns: 1fr; }

  footer {
    grid-template-columns: 1fr 1fr;
    gap: 36px;
    padding: 48px var(--px) 28px;
  }
  .ft-brand { grid-column: 1 / -1; }
}

/* ============================================================
   RESPONSIVE — MOBILE (<=768px)
   ============================================================ */
@media (max-width: 768px) {
  :root { --px: 24px; }

  nav { padding: 18px var(--px); }
  .nav-logo svg { width: 38px; height: 35px; }

  .hero { min-height: 600px; }
  .hero-c { padding-bottom: 48px; }
  .hero-ar { font-size: clamp(32px, 8vw, 48px); }
  .hero-ar-en { font-size: 11px; margin-top: 10px; }
  .hero-lbl { font-size: 8px; }
  .hero-desc { font-size: 13px; }
  .hero-btn { padding: 14px 28px; font-size: 9px; }
  .scroll-hint { bottom: 16px; }
  .scroll-line { height: 30px; }

  .staff-section { height: 70vh; min-height: 460px; }
  .staff-ov { padding-bottom: 48px; }
  .staff-h { font-size: clamp(32px, 7vw, 52px); }
  .staff-en { font-size: clamp(11px, 3vw, 16px); }

  .cs-text { padding: 40px var(--px); }
  .cs-body { font-size: 13px; }

  .exp-n { font-size: 42px; }
  .exp-title { font-size: 19px; }

  .services { padding: 64px var(--px); }
  .svc-card { padding: 36px 28px; }
  .svc-ar { font-size: 23px; }

  .booking { padding: 80px var(--px); }
  .bk-h2 { font-size: clamp(36px, 9vw, 60px); }
  .bk-en { font-size: clamp(12px, 3.5vw, 18px); margin-bottom: 32px; }
  .bk-btn { padding: 16px 40px; font-size: 10px; }
  .bk-contact { font-size: 10px; margin-top: 28px; }

  footer {
    grid-template-columns: 1fr;
    gap: 32px;
    padding: 40px var(--px) 24px;
  }
  .ft-brand { grid-column: auto; }
  .ft-bottom { flex-direction: column; gap: 16px; text-align: center; }
}

/* ============================================================
   RESPONSIVE — SMALL MOBILE (<=480px)
   ============================================================ */
@media (max-width: 480px) {
  :root { --px: 20px; }

  .hero { min-height: 560px; }
  .hero-ar { font-size: clamp(28px, 7vw, 40px); }
  .hero-btn { width: 100%; justify-content: center; padding: 16px 24px; }

  .staff-section { height: 60vh; min-height: 400px; }
  .staff-h { font-size: clamp(26px, 6vw, 40px); }

  .cs-img { height: 40vh; min-height: 260px; }
  .cs-text { padding: 32px var(--px); gap: 18px; }
  .cs-h { font-size: clamp(24px, 6vw, 36px); }

  .exp-n { font-size: 36px; }
  .exp-title { font-size: 17px; }
  .exp-desc { font-size: 12px; }

  .svc-card { padding: 28px 20px; }
  .svc-ar { font-size: 20px; }
  .svc-en { font-size: 11px; }

  .booking { padding: 64px var(--px); }
  .bk-h2 { font-size: clamp(30px, 8vw, 48px); }
  .bk-btn { padding: 14px 32px; font-size: 9px; width: 100%; text-align: center; }

  .contact-page { padding: 100px var(--px) 40px; }
  .contact-card { padding: 20px 24px; gap: 16px; }
  .contact-icon { width: 24px; height: 24px; }
}

/* ============================================================
   PRINT
   ============================================================ */
@media print {
  nav,
  .scroll-hint,
  .nav-toggle,
  .nav-mobile { display: none !important; }
  .hero { min-height: auto; height: auto; }
  body { background: #fff; color: #000; }
}
